import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.some.js";
/* eslint-disable */
import { API, graphqlOperation } from "aws-amplify";
import { master_leave_settings, edit_organization } from "@/graphql/mutations.js";
import Snackbar from "@/components/SnackBar.vue";
import LeaveApprovals from "@/components/PresenceApp/AdminLevelComponents/LeaveApprovals.vue";
export default {
  components: {
    Snackbar,
    LeaveApprovals
  },
  data() {
    return {
      SnackBarComponent: {},
      typeLeave: "Days",
      corection_data: "",
      number_rules: [v => !!v || "required ", value => /^\d+$/.test(value) || "Only numbers are allowed"],
      noOFDays: "",
      duartionitem: ["Days", "Months"],
      height: 0,
      tableData: [],
      tableLoading: false,
      loading: false,
      fixed: true,
      headers: [{
        title: "Leave Name",
        key: "duration_name",
        sortable: false
      }, {
        title: "Days",
        key: "duration_value",
        sortable: false
      }, {
        title: "Action",
        key: "actions",
        sortable: false
      }],
      singleSelect: false,
      selected: [],
      addDaysWC: false,
      checkboxSelectedValue: null,
      weekCompDays: null,
      savedArray: [],
      actualRespone: [],
      enableCompoff: false,
      enableWeekoff: false,
      weekOffCheck: false,
      compOffCheck: false
    };
  },
  created() {
    this.weekOffCheck = false;
    this.compOffCheck = false;
    this.height = window.innerHeight - 370;
    this.get_leave();
  },
  methods: {
    delet_leave(item) {
      for (let i = 0; i < this.tableData.length; i++) {
        if (item.duration_name == this.tableData[i].duration_name) {
          this.tableData.splice(i, 1);
        }
      }
    },
    save_action() {
      var data = [];
      this.tableData.forEach(element => {
        data.push({
          duration_name: element.duration_name,
          duration_value: element.duration_value,
          duration_type: "Days"
        });
      });
      const weekOffExists = this.actualRespone.some(item => item.duration_name === "u/o");
      const compOffExists = this.actualRespone.some(item => item.duration_name === "c/o");
      if (compOffExists && this.enableCompoff) {
        data.push({
          duration_name: "c/o",
          duration_value: "365",
          duration_type: "Days"
        });
      } else if (!compOffExists && this.enableCompoff) {
        data.push({
          duration_name: "c/o",
          duration_value: "365",
          duration_type: "Days"
        });
      }
      if (weekOffExists && this.enableWeekoff) {
        data.push({
          duration_name: "u/o",
          duration_value: "365",
          duration_type: "Days"
        });
      } else if (!weekOffExists && this.enableWeekoff) {
        data.push({
          duration_name: "u/o",
          duration_value: "365",
          duration_type: "Days"
        });
      }
      this.savedArray = data;
      return data;
    },
    fetch_value(value) {
      if (value == "comp-off") {
        this.compOffCheck = true;
      } else {
        this.weekOffCheck = true;
      }
    },
    get_value(value) {
      if (value.selected == true) {
        this.weekCompDays = null;
        this.checkboxSelectedValue = value;
        this.addDaysWC = true;
      } else {
        for (let i = 0; i < this.tableData.length; i++) {
          if (value.duration_name == this.tableData[i].duration_name) {
            this.tableData[i].selected = false;
          }
        }
      }
    },
    close_dialog() {
      this.addDaysWC = false;
    },
    async add_action(corection_data) {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        const key_object = {
          duration_name: corection_data,
          duration_value: this.noOFDays,
          duration_type: this.typeLeave
        };
        const hasMatchingCode = this.tableData.some(obj => obj.duration_name === corection_data);
        if (!hasMatchingCode) {
          this.tableData.push(key_object);
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            Top: true,
            SnackbarText: "Leave already exists"
          };
        }
        this.corection_data = "";
        this.noOFDays = "";
        this.$refs.form.resetValidation();
      } else {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          Top: true,
          SnackbarText: "Please fill the form correctly"
        };
      }
    },
    async get_leave() {
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(master_leave_settings, {
          input: {
            action_type: "GET",
            organization_id: data.organization.organization_id
          }
        }));
        this.tableData = [];
        this.actualRespone = [];
        var response = JSON.parse(result.data.master_leave_settings);
        if (response.Status == "SUCCESS") {
          this.actualRespone = response.data[0].leave_types == undefined ? [] : response.data[0].leave_types;
          this.actualRespone.forEach(element => {
            if (element.duration_name != "u/o" && element.duration_name != "c/o") {
              this.tableData.push(element);
            }
          });
          const weekOffExists = this.actualRespone.some(item => item.duration_name === "u/o");
          const compOffExists = this.actualRespone.some(item => item.duration_name === "c/o");
          if (weekOffExists) {
            this.enableWeekoff = true;
          }
          if (compOffExists) {
            this.enableCompoff = true;
          }
        }
      } catch (err) {
        this.overlay = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          Top: true,
          SnackbarText: err.errors[0].message
        };
      }
    },
    async fetch_org_level_update() {
      this.savedArray = [];
      await this.save_action();
      const weekOffExists = this.savedArray.some(item => item.duration_name === "u/o");
      var weekOfObject = this.$store.getters.GetOrgDetails.organization.week_off;
      var allFalse = true;
      for (var key in weekOfObject) {
        if (weekOfObject[key] === true) {
          allFalse = false;
          break;
        }
      }
      if (allFalse || weekOffExists == false) {
        this.save_mutation();
      } else {
        this.savedArray.forEach(element => {
          if (element.duration_name == "u/o") {
            this.SnackBarComponent = {
              SnackbarVmodel: true,
              SnackbarColor: "red",
              Top: true,
              SnackbarText: "Please remove organization week off to enable this settings"
            };
          }
        });
      }
      // console.log(allFalse);
    },
    async save_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(master_leave_settings, {
          input: {
            action_type: "CREATE",
            organization_id: data.organization.organization_id,
            leave_types: this.save_action()
          }
        }));
        var response = JSON.parse(result.data.master_leave_settings);
        if (response.Status == "SUCCESS") {
          await this.get_leave();
          this.update_org_settisng();
          this.weekOffCheck = false;
          this.compOffCheck = false;
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            Top: true,
            SnackbarText: response.Message
          };
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            Top: true,
            SnackbarText: response.Message
          };
        }
        this.loading = false;
      } catch (err) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          Top: true,
          SnackbarText: err.errors[0].message
        };
        this.loading = false;
      }
    },
    async update_org_settisng() {
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(edit_organization, {
          input: {
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id,
            comp_off: this.fetch_comff(),
            week_off_settings: this.fetch_boolen_value()
          }
        }));
        var response = JSON.parse(result.data.edit_organization);
        if (response.Status == "SUCCESS") {
          await this.get_Org_details();
          this.$store.commit("SetOrgDetails", this.orgDetails);
        } else {}
      } catch (error) {}
    },
    fetch_comff() {
      var data = null;
      const compOffExists = this.actualRespone.some(item => item.duration_name === "c/o" && item.duration_value != "0");
      if (!compOffExists) {
        data = false;
      } else {
        data = true;
      }
      return data;
    },
    fetch_boolen_value() {
      var data = null;
      const weekOffExists = this.actualRespone.some(item => item.duration_name === "u/o" && item.duration_value != "0");
      if (!weekOffExists) {
        data = false;
      } else {
        data = true;
      }
      return data;
    }
  }
};
